"""字幕与文字层：ASS 烧录用 libass，另附 SRT 方便二剪。

时间轴支持两种传法：
- 老路子：按镜头 duration 累加
- 有转场时：显式传每个镜头的起点（因为相邻镜头会重叠）
"""

from __future__ import annotations

import re
from pathlib import Path
from typing import List, Sequence

from ..config import RenderConfig
from ..schemas import Shot

ASS_HEADER = """[Script Info]
; Generated by VisionForge
ScriptType: v4.00+
PlayResX: {w}
PlayResY: {h}
WrapStyle: 2
ScaledBorderAndShadow: yes
YCbCr Matrix: TV.709

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: VF,{font},{size},{color},&H000000FF,&H00141414,&H64000000,-1,0,0,0,100,100,1,0,1,{outline},2,2,{ml},{mr},{mv},1
Style: VF_TITLE_TOP,{font},{tsize},&H00FFFFFF,&H000000FF,&H00101010,&H78000000,-1,0,0,0,100,100,1,0,1,4,3,8,{ml},{mr},{tmv},1
Style: VF_TITLE_CENTER,{font},{tsize},&H00FFFFFF,&H000000FF,&H00101010,&H78000000,-1,0,0,0,100,100,1,0,1,4,3,5,{ml},{mr},0,1
Style: VF_TITLE_BOTTOM,{font},{tsize},&H00FFFFFF,&H000000FF,&H00101010,&H78000000,-1,0,0,0,100,100,1,0,1,4,3,2,{ml},{mr},{tmv},1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
"""

POSITION_STYLE = {"top": "VF_TITLE_TOP", "center": "VF_TITLE_CENTER", "bottom": "VF_TITLE_BOTTOM"}


def _ts(seconds: float) -> str:
    seconds = max(0.0, seconds)
    h = int(seconds // 3600)
    m = int((seconds % 3600) // 60)
    s = seconds % 60
    return f"{h}:{m:02d}:{s:05.2f}"


def _escape(text: str) -> str:
    text = (text or "").replace("\\", "\\\\").replace("{", "（").replace("}", "）")
    return text.replace("\r", "").strip()


def wrap_text(text: str, max_chars: int = 18, max_lines: int = 2) -> str:
    """中文按字数折行，英文按词折行；返回用 ASS 换行符拼接的文本。"""
    text = _escape(text)
    if not text:
        return ""
    if "\n" in text:
        return "\\N".join(_escape(line) for line in text.splitlines()[:max_lines])

    if " " in text:
        words, lines, cur = text.split(), [], ""
        for w in words:
            cand = f"{cur} {w}".strip()
            if len(cand) > max_chars * 1.6 and cur:
                lines.append(cur)
                cur = w
            else:
                cur = cand
        if cur:
            lines.append(cur)
    else:
        lines = [text[i:i + max_chars] for i in range(0, len(text), max_chars)]

    if len(lines) > max_lines:
        lines = lines[:max_lines]
        lines[-1] = lines[-1][: max(1, max_chars - 1)] + "…"
    return "\\N".join(lines)


def _header(cfg: RenderConfig) -> str:
    return ASS_HEADER.format(
        w=cfg.width, h=cfg.height, font=cfg.subtitle_font, size=cfg.subtitle_size,
        tsize=max(28, int(cfg.subtitle_size * 1.25)),
        color=cfg.subtitle_color, outline=cfg.subtitle_outline,
        ml=int(cfg.width * 0.08), mr=int(cfg.width * 0.08),
        mv=cfg.subtitle_margin_v, tmv=max(60, int(cfg.height * 0.09)),
    )


def build_ass(shots: Sequence[Shot], cfg: RenderConfig, *, offset: float = 0.0,
              durations: Sequence[float] | None = None,
              starts: Sequence[float] | None = None) -> str:
    body: List[str] = []
    cursor = offset
    for i, shot in enumerate(shots):
        dur = max(0.5, float(durations[i] if durations and i < len(durations) else shot.duration))
        start_at = float(starts[i]) if starts and i < len(starts) else cursor
        text = shot.text.strip()
        if text:
            start = start_at + 0.12
            end = min(start_at + dur - 0.08, start + max(1.2, dur - 0.2))
            if starts and i + 1 < len(starts):
                end = min(end, float(starts[i + 1]) - 0.05)   # 转场重叠时别两条字幕抢镜
            if shot.audio_duration:
                end = min(end, start + shot.audio_duration + 0.9)
            if end > start:
                body.append(f"Dialogue: 0,{_ts(start)},{_ts(end)},VF,,0,0,0,,{wrap_text(text)}")
        cursor = start_at + dur
    return _header(cfg) + "\n".join(body) + "\n"


def write_ass(path: Path, shots: Sequence[Shot], cfg: RenderConfig, *,
              offset: float = 0.0, durations: Sequence[float] | None = None,
              starts: Sequence[float] | None = None) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(build_ass(shots, cfg, offset=offset, durations=durations, starts=starts),
                    encoding="utf-8")
    return path


def build_title_ass(shots: Sequence[Shot], cfg: RenderConfig, *,
                    durations: Sequence[float] | None = None,
                    starts: Sequence[float] | None = None,
                    offset: float = 0.0) -> str:
    """花字/标题层：单独一条 ASS，避免和字幕样式互相打架。"""
    body: List[str] = []
    cursor = offset
    for i, shot in enumerate(shots):
        dur = max(0.5, float(durations[i] if durations and i < len(durations) else shot.duration))
        start_at = float(starts[i]) if starts and i < len(starts) else cursor
        text = (shot.title_text or "").strip()
        if text:
            style = POSITION_STYLE.get(shot.title_position or "bottom", "VF_TITLE_BOTTOM")
            size = int(shot.title_size or 0) or max(30, int(cfg.subtitle_size * 1.25))
            body.append(
                f"Dialogue: 1,{_ts(start_at + 0.15)},{_ts(start_at + dur - 0.15)},{style},"
                f",0,0,0,,{{\\fs{size}}}{wrap_text(text, 22, 2)}"
            )
        cursor = start_at + dur
    return _header(cfg) + "\n".join(body) + "\n"


def write_title_ass(path: Path, shots: Sequence[Shot], cfg: RenderConfig, *,
                    durations: Sequence[float] | None = None,
                    starts: Sequence[float] | None = None,
                    offset: float = 0.0) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(build_title_ass(shots, cfg, durations=durations, starts=starts, offset=offset),
                    encoding="utf-8")
    return path


def write_srt(path: Path, shots: Sequence[Shot], *, offset: float = 0.0,
              durations: Sequence[float] | None = None,
              starts: Sequence[float] | None = None) -> Path:
    def fmt(t: float) -> str:
        h, rem = divmod(max(0.0, t), 3600)
        m, s = divmod(rem, 60)
        return f"{int(h):02d}:{int(m):02d}:{int(s):02d},{int((s - int(s)) * 1000):03d}"

    lines, cursor, idx = [], offset, 1
    for i, shot in enumerate(shots):
        text = shot.text.strip()
        dur = float(durations[i] if durations and i < len(durations) else shot.duration)
        start_at = float(starts[i]) if starts and i < len(starts) else cursor
        if text:
            lines += [str(idx), f"{fmt(start_at + 0.1)} --> {fmt(start_at + dur - 0.1)}",
                      re.sub(r"\\N", "\n", wrap_text(text)), ""]
            idx += 1
        cursor = start_at + dur
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines), encoding="utf-8")
    return path
